-- Europa 1400 - Live State Snapshot
--
-- Captures a coherent cross-domain snapshot using the domain helpers
-- (player/world/economy/quest/social/state) so `report`/`session`
-- can persist domain values alongside memory. All reads are pcall-guarded
-- so a missing catalog registration just leaves that field nil.
--
--   snapshot = require("snapshot")  -- or already `snapshot`
--   local s = snapshot.capture()          -- table with time/year/gold/fame/etc
--   snapshot.print(s)                     -- pretty print
--   snapshot.save("snap1.lua")            -- persist via session/report
--   local a = snapshot.capture(); -- ... do action ...; local b = snapshot.capture()
--   snapshot.diff(a, b)                   -- what changed

local M = {}

local function try(fn, ...)
    local ok, r = pcall(fn, ...)
    if ok then return r end
    return nil
end

function M.capture()
    local s = { _t = os.date("%Y-%m-%d %H:%M:%S") }
    local w = require("world")
    local p = require("player")
    local e = require("economy")
    local q = require("quest")
    local so = require("social")
    local st = require("state")
    local g = _G.game

    if w then
        s.time = try(w.time); s.year = try(w.year); s.season = try(w.season)
        s.speed = try(w.speed); s.difficulty = try(w.difficulty); s.paused = try(w.is_paused)
    end
    if st and not s.paused then s.game_state = try(st.get) end
    if g then
        -- try indexed player 0 for legacy saves
        s.gold = try(g.call, "GetPlayerGold") or try(g.call, "GetPlayerGoldRaw", 0) or try(g.call, "GetCityGold", 0)
        s.fame = try(g.call, "GetPlayerFame") or try(g.call, "GetReputation", 0, 0)
        s.health = try(g.call, "GetPlayerHealth", 0)
        s.level = try(g.call, "GetPlayerLevel")
    end
    if so then
        s.nobility = try(so.nobility, 0)
        s.privileges = try(so.privileges, 0)
    end
    if e then
        -- sample a few market prices / guild balances without spamming
        -- opt-in heavy fields: only if _G._snapshot_market is truthy or new supply/demand helpers present? keep light by default
        s.sample_market = {}
        for _, goodId in ipairs({0, 3, 8, 12}) do
            local v = try(e.market_price, goodId, 0)
            if v ~= nil then s.sample_market[goodId] = v end
        end
        s.sample_guild = try(e.guild_balance, 0)
        s.sample_tax = try(e.tax_rate, 0, 0)
        s.sample_stock = try(e.stock, 0, 0)
        s.sample_income = try(e.daily_income, 0)
        if _G._snapshot_extended then
            -- include extended keys in print order
            s.sample_supply = try(e.supply, 0, 3)
            s.sample_demand = try(e.demand, 0, 3)
            s.sample_trade_profit = try(e.trade_profit, 0, 1, 3)
            s.sample_inventory_value = try(e.inventory_value, _G._sample_building or 0)
        end
    end
    if w then
        s.city_owner_0 = try(w.city_owner, 0)
        s.office_0_0 = try(w.office, 0, 0)
    end
    if q then
        s.quest_0_status = try(q.status, 0)
    end
    local cv = require("civic")
    if cv then
        s.sample_efficiency = try(cv.efficiency, 0)
        s.sample_morale = try(cv.morale, 0)
        s.sample_crime = try(cv.crime, 0)
        s.sample_votes = try(cv.votes, 0, 0)
        s.sample_bribe = try(_G.economy and _G.economy.bribe_price, 0, 1)
    end
    if so then
        s.sample_intrigue = try(so.intrigue, 0, 1)
        s.sample_aggressiveness = try(so.aggressiveness, 0)
        s.sample_title_available = try(so.is_title_available, 1)
        s.sample_title_cost = try(so.title_cost, 1) or try(e and e.title_cost, 1)
        s.sample_influence = try(so.influence, 0, 0)
        s.sample_guild_rep = try(so.guild_reputation, 0, 1)
        s.sample_dynasty_cash = try(so.dynasty_cash, 0)
        s.sample_court_influence = try(so.court_influence, 0)
        do
            local fn
            if so and so.bribe_cost then fn = function() return so.bribe_cost(0,1) end
            elseif _G.world and _G.world.office_bribe_cost then fn = function() return _G.world.office_bribe_cost(0,1) end
            end
            if fn then s.sample_bribe_cost = try(fn) end
        end
        if _G._snapshot_extended then
            s.sample_relation = try(so.relation, 0, 1)
            s.sample_faith = try(so.faith, 0)
            s.sample_piety = try(so.piety, 0)
            s.sample_prestige = try(so.prestige, 0)
            s.sample_court_favor = try(so.court_favor, 0, 1)
            s.sample_disease = try(so.disease, 0)
            s.sample_court_rank = try(so.court_rank, 0)
            s.sample_ai_behavior = try(so.ai_behavior, 0)
            s.sample_tithe = try(so.tithe, 0)
            s.sample_debt = try(e and e.debt, 0)
            s.sample_bank = try(e and e.bank, 0)
            s.sample_loan = try(e and e.loan, 0, 1)
            s.sample_interest = try(e and e.interest, 0)
            -- dynasty rep etc: extended-only to avoid noise
            s.sample_dynasty_rep = try(so.dynasty_reputation, 0)
            s.sample_family_wealth = try(so.family_wealth, 0)
            s.sample_building_tax = try(_G.civic and _G.civic.building_tax, _G._sample_building or 0)
            s.sample_worker_skill = try(_G.civic and _G.civic.worker_skill, 0, 0)
            -- 245-batch: court/assassin/warrant/verdict, 253-batch: poison/drunk/title_tier/evidence
            s.sample_court_level = try(so.court_influence_level, 0, 1)
            s.sample_assassin = try(so.assassin_level, 0)
            s.sample_warrant = try(so.arrest_warrant, 0)
            s.sample_verdict = try(_G.civic and _G.civic.trial_verdict, 0)
            s.sample_poison = try(so.poison, 0)
            s.sample_drunk = try(so.drunk, 0)
            s.sample_title_tier = try(so.title_tier, 0)
            s.sample_evidence = try(so.evidence, 0)
            s.sample_jail_time = try(so.jail_time, 0)
            s.sample_public_order = try(so.public_order, 0) or try(w and w.public_order, 0)
            s.sample_harvest = try(_G.civic and _G.civic.harvest_yield, _G._sample_building or 0, 0)
            -- economy yield family
            if _G._snapshot_extended then
                local ey=_G.economy
                if ey then
                    local b=_G._sample_building or 0
                    if ey.dairy_yield then s.sample_dairy_yield2 = try(ey.dairy_yield, b, 0) end
                    if ey.fishing_yield then s.sample_fishing_yield2 = try(ey.fishing_yield, b, 0) end
                    if ey.hunting_yield then s.sample_hunting_yield2 = try(ey.hunting_yield, b, 0) end
                    if ey.pasture_yield then s.sample_pasture_yield2 = try(ey.pasture_yield, b, 0) end
                    if ey.apiary_yield then s.sample_apiary_yield2 = try(ey.apiary_yield, b, 0) end
                    if ey.orchard_yield then s.sample_orchard_yield2 = try(ey.orchard_yield, b, 0) end
                    if ey.chandler_yield then s.sample_chandler_yield2 = try(ey.chandler_yield, b, 0) end
                    if ey.quarry_yield then s.sample_quarry_yield2 = try(ey.quarry_yield, b, 0) end
                    if ey.falconer_yield then s.sample_falconer_yield2 = try(ey.falconer_yield, b, 0) end
                    if ey.shepherd_yield then s.sample_shepherd_yield2 = try(ey.shepherd_yield, b, 0) end
                    if ey.miller_yield then s.sample_miller_yield2 = try(ey.miller_yield, b, 0) end
                    if ey.fishery_yield then s.sample_fishery_yield2 = try(ey.fishery_yield, b, 0) end
                    if ey.fowler_yield then s.sample_fowler_yield2 = try(ey.fowler_yield, b, 0) end
                    if ey.distiller_yield then s.sample_distiller_yield2 = try(ey.distiller_yield, b, 0) end
                    if ey.mining_yield then s.sample_mining_yield2 = try(ey.mining_yield, b, 0) end
                    if ey.logging_yield then s.sample_logging_yield2 = try(ey.logging_yield, b, 0) end
                end
            end

            s.sample_city_rank = try(w and w.city_rank, 0)
            s.sample_city_prestige = try(w and w.city_prestige, 0)
            -- public order already above; plus new 270-batch
            if so and so.city_favor then s.sample_city_favor = try(so.city_favor, 0, 0) end
            if not s.sample_city_favor and w and w.city_favor then s.sample_city_favor = try(w.city_favor, 0, 0) end
            if w and w.office_term then s.sample_office_term = try(w.office_term, 0, 0) end
            if e and e.guild_fee then s.sample_guild_fee = try(e.guild_fee, 0) end
            do
                local bid = _G._sample_building
                local bl = require("building")
                if bid and bl and bl.at then
                    local ok,b = pcall(bl.at, bid)
                    if ok and b then
                        if b.servants then s.sample_servants = try(function() return b:servants() end) end
                        if b.slots then s.sample_slots = try(function() return b:slots() end) end
                    end
                end
            end
            if w and w.militia then s.sample_militia = try(w.militia, 0) end
            if w and w.wall_health then s.sample_wall = try(w.wall_health, 0) end
            if _G.civic and _G.civic.witnesses then s.sample_witnesses = try(_G.civic.witnesses, 0) end
            if _G.civic and _G.civic.worker_wage then s.sample_wage = try(_G.civic.worker_wage, _G._sample_building or 0, 0) end
            if so and so.spy_network then s.sample_spy_network = try(so.spy_network, 0, 0) end
            if so and so.age then s.sample_age = try(so.age, 0) end
            if so and so.heir then s.sample_heir = try(so.heir, 0) end
