            if so and so.kidnap_chance then s.sample_kidnap = try(so.kidnap_chance, 0, 1) end
            if so and so.ransom then s.sample_ransom = try(so.ransom, 0) end
            if w and w.unrest then s.sample_unrest = try(w.unrest, 0) end
