otism","sample_bishop","sample_road","sample_btax","sample_route_profit","sample_caravan","sample_imperial","sample_tavern","sample_monastery","sample_title_rank","sample_plague","sample_apprentice_slots","sample_wall_cost","sample_fair","sample_granary","sample_baker_bonus","sample_master_bribe","sample_gambling","sample_toll","sample_escort","sample_gates","sample_decay","sample_banquet","sample_road_upkeep","sample_stalls","sample_harbor","sample_cathedral","sample_alms","sample_indulgence","sample_decay2","sample_sin","sample_confession","sample_excomm","sample_promo_cost","sample_tax_income","sample_upgrade_cost","sample_university","sample_guard_morale","sample_pilgrim","sample_relic","sample_crusade","sample_joust","sample_tournament","sample_inquisition","sample_militia_upkeep","sample_smuggler","sample_brewery","sample_mill","sample_harbor_fee","sample_festival_cost","sample_cartel","sample_fence","sample_jester","sample_bard","sample_stall_rent","sample_church_tax","sample_blacksmith","sample_dowry","sample_wedding","sample_patrician","sample_tannery","sample_weaver","sample_mint","sample_herb","sample_market_fee","sample_vineyard","sample_pottery","sample_tailor","sample_fishing","sample_orchard","sample_carpenter","sample_ropemaker","sample_apiary","sample_hunting","sample_alchemist","sample_glassworks","sample_mason","sample_distillery","sample_pasture","sample_quarry","sample_forge","sample_sawmill","sample_kiln","sample_foundry","sample_pop_limit","sample_growth","sample_apoth","sample_scribe","sample_goldsmith","sample_falconer","sample_jeweler","sample_bath","sample_perfumer","sample_soap","sample_candle","sample_paper","sample_printing","sample_toolmaker","sample_charcoal","sample_furrier","sample_road_toll","sample_church_corr"}
    local seen = {}
    for _, k in ipairs(order) do
        if s[k] ~= nil then
            local v = s[k]
            local extra = ""
            if k == "season" and type(v)=="number" then
                local enums = require("enums")
                if enums and enums.lookup then local ok, n = pcall(enums.lookup, "season", v); if ok and n then extra = " ("..n..")" end end
            elseif k == "difficulty" and type(v)=="number" then
                local enums = require("enums")
                if enums and enums.lookup then local ok, n = pcall(enums.lookup, "difficulty", v); if ok and n then extra = " ("..n..")" end end
            end
            print(string.format("  %-16s = %s%s", k, tostring(v), extra))
            seen[k]=true
        end
    end
    for k, v in pairs(s) do
        if k ~= "_t" and k ~= "sample_market" and not seen[k] and v ~= nil then
            print(string.format("  %-16s = %s", k, tostring(v)))
        end
    end
    if s.sample_market then
        print("  sample_market:")
        for gid, price in pairs(s.sample_market) do
            local name = nil
            local enums = require("enums")
            if enums and enums.lookup then
                local ok, n = pcall(enums.lookup, "good", gid)
                if ok then name = n end
            end
            print(string.format("    good %d (%s) -> %s", gid, name or "?", tostring(price)))
        end
    end
    return s
end

function M.diff(a, b)
    if not a or not b then error("diff(a,b) requires two snapshots (use snapshot.capture)") end
    local changed = {}
    local keys = {}
    for k in pairs(a) do keys[k]=true end
    for k in pairs(b) do keys[k]=true end
    for k in pairs(keys) do
        if k ~= "_t" and k ~= "sample_market" then
            if tostring(a[k]) ~= tostring(b[k]) then
                changed[k] = { from = a[k], to = b[k] }
                print(string.format("  %-16s: %s -> %s", k, tostring(a[k]), tostring(b[k])))
            end
        end
    end
    -- market sub-diff
    if a.sample_market or b.sample_market then
        local am = a.sample_market or {}; local bm = b.sample_market or {}
        for gid, av in pairs(am) do
            local bv = bm[gid]
            if tostring(av) ~= tostring(bv) then
                changed["market_"..gid] = { from=av, to=bv }
                print(string.format("  market good %d: %s -> %s", gid, tostring(av), tostring(bv)))
            end
        end
        for gid, bv in pairs(bm) do if am[gid]==nil then changed["market_"..gid]={from=nil,to=bv}; print(string.format("  market good %d: nil -> %s", gid, tostring(bv))) end end
    end
    if next(changed)==nil then print("snapshot.diff: no changes") end
    return changed
end

function M.save(path, s)
    s = s or M.capture()
    local sess = require("session")
    path = path or "snapshot.lua"
    local f, err = io.open(path, "w")
    if not f then error("cannot open " .. path .. ": " .. tostring(err)) end
    f:write("-- snapshot " .. tostring(s._t or os.date()) .. "\nreturn {\n")
    for k, v in pairs(s) do
        if k == "sample_market" then
            f:write("  sample_market = { "); for gid, price in pairs(v) do f:write(string.format("[%d]=%s, ", gid, tostring(price))) end; f:write("},\n")
        elseif type(v)=="number" then f:write(string.format("  %s = %d,\n", k, v))
        elseif type(v)=="string" then f:write(string.format("  %s = %q,\n", k, v))
        elseif v==nil then -- skip
        else f:write(string.format("  -- %s = %s\n", k, tostring(v))) end
    end
    f:write("}\n")
    f:close()
    print(string.format("snapshot.save: -> %s", path))
    if sess and sess.note then pcall(sess.note, "snapshot -> " .. path) end
    return path
end

return M
